    "services.eyebrow": "Dienste",
    "services.h1": "Dienste für Freunde & Familie",
    "services.subtitle": "Einige self-hostete Dinge, die ich teile. Die meisten benötigen eine Account oder ein Einladungsnachricht — schreib mir und ich setze dich ein.",
    "services.plex.name": "Plex",
